begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,is_anonymous,raw_user_meta_data) values
 ('f3000000-0000-4000-8000-000000000001',true,'{}'),
 ('f3000000-0000-4000-8000-000000000002',true,'{"role":"moderator","is_admin":true}'),
 ('f3000000-0000-4000-8000-000000000003',false,'{}');
insert into contribution_private.moderators(user_id) values('f3000000-0000-4000-8000-000000000003');
create function pg_temp.payload(n integer default 1) returns jsonb language sql as $$
  select jsonb_build_object('destination_slug','nha-trang','title','Original test pin '||n,'description','Original user text with permission','address',null,
    'location',jsonb_build_object('lat',12.24,'lng',109.19),'categories',jsonb_build_array('nature'),'tags','[]'::jsonb,
    'suggested_duration_min',60,'transport_constraint','access_unverified','source','original_user_contribution','rights_confirmed',true);
$$;
grant execute on function pg_temp.payload(integer) to authenticated;
select ok((select not rolcanlogin and not rolsuper and not rolbypassrls and not rolinherit from pg_roles where rolname='contribution_writer'),'dedicated role cannot login/inherit/bypass RLS');
select ok(not has_schema_privilege('contribution_writer','public','CREATE'),'writer cannot create objects');
select ok(not has_table_privilege('contribution_writer','places','UPDATE'),'writer cannot edit editorial');
select ok(not has_table_privilege('authenticated','place_submissions','INSERT'),'no direct owner insert');
select ok(not has_table_privilege('authenticated','place_submissions','UPDATE'),'no direct owner approval');
select ok(not has_table_privilege('authenticated','place_submission_events','INSERT'),'no forged audit');
select ok(not has_table_privilege('authenticated','contribution_private.moderators','INSERT'),'no moderator enrollment');
select ok(not has_function_privilege('anon','public.submit_place(jsonb,uuid)','EXECUTE'),'anon cannot submit without session');
select ok(not has_function_privilege('anon','public.contribution_session_info()','EXECUTE'),'anon cannot inspect private session capability');
select ok(public.contribution_valid_payload(pg_temp.payload()),'valid original contribution');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('owner_id','forged')),'reject owner injection');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('source','google')),'reject restricted provider source');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('rights_confirmed',false)),'require permission');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('hours','verified')),'cannot assert verified hours');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('title',repeat('x',161))),'bound title');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('description',E'private\ncontrol')),'reject control characters');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('categories',jsonb_build_array('nature','nature'))),'reject repeated categories');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('location',jsonb_build_object('lat',91,'lng',0))),'reject latitude bounds');
select ok(not public.contribution_valid_payload(pg_temp.payload()||jsonb_build_object('suggested_duration_min',30.5)),'duration must be integer');
select ok(not public.contribution_valid_payload(jsonb_set(pg_temp.payload(),array[key],'null')),key||' null cannot bypass validation')
  from unnest(array['destination_slug','title','description','location','categories','tags','suggested_duration_min','transport_constraint','source','rights_confirmed']) key;
select ok(not public.contribution_valid_payload(pg_temp.payload()-key),key||' cannot be omitted')
  from unnest(array['destination_slug','title','description','address','location','categories','tags','suggested_duration_min','transport_constraint','source','rights_confirmed']) key;

select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is(submit_place(pg_temp.payload(),'f3400000-0000-4000-8000-000000000001')->>'status','submitted','owner creates private submission');
select is((select count(*)::integer from place_submissions),1,'owner can load own submission');
select is((select count(*)::integer from place_submission_events),1,'owner can read own audit');
select is(submit_place(pg_temp.payload(),'f3400000-0000-4000-8000-000000000001')->>'status','replayed','exact retry replays');
select is(submit_place(pg_temp.payload(2),'f3400000-0000-4000-8000-000000000001')->>'status','idempotency_conflict','changed request key conflicts');
select is(submit_place(pg_temp.payload(),'f3400000-0000-4000-8000-000000000002')->>'status','duplicate','identical payload different key does not spam');
select is((select count(*)::integer from place_submissions),1,'retry/duplicate create no extra rows');
select is(transition_place_submission((select id from place_submissions),1,'approve','Owner forged approval')->>'status','transition_denied','owner cannot self-approve');
select is(jsonb_array_length(list_community_places('nha-trang')),0,'submitted is not public');
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000002',true);
select ok(not contribution_private.is_moderator(),'user metadata does not grant moderator rights');
select is(contribution_session_info()->>'moderator','false','public session RPC does not trust metadata');
select is((select count(*)::integer from place_submissions),0,'owner B cannot read A');
select is((select count(*)::integer from place_submission_events),0,'owner B cannot read A audit');
reset role;
select set_config('test.submission_id',(select id::text from place_submissions limit 1),true);
set local role authenticated;
select is(transition_place_submission(current_setting('test.submission_id')::uuid,1,'withdraw')->>'status','not_found','B cannot withdraw A even knowing UUID');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,1,'verify')->>'status','not_found','B cannot moderate via metadata');
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000003',true);
select ok(contribution_private.is_moderator(),'admin-managed member can moderate');
select is(contribution_session_info()->>'moderator','true','public session RPC returns only own verified capability');
select is((select count(*)::integer from jsonb_object_keys(contribution_session_info())),1,'session RPC has no membership roster or owner token');
select is((select count(*)::integer from place_submissions),1,'moderator can inspect private queue');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,1,'approve','Reviewed original text')->>'status','transition_denied','cannot skip verification');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,1,'verify')->>'state','verification','start verification');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,1,'reject','Stale review note')->>'status','version_conflict','stale moderator cannot overwrite');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,2,'approve','')->>'status','transition_denied','approval requires review note');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,2,'approve','Reviewed original text and pin')->>'state','approved','verified workflow permits community publication');
set local role anon;
select throws_ok($$select * from place_submissions$$,'42501',null,'anon cannot read raw submissions');
select throws_ok($$select * from place_submission_events$$,'42501',null,'anon cannot read raw audit');
select is(jsonb_array_length(list_community_places('nha-trang')),1,'public sees approved projection');
select is(jsonb_array_length(list_community_places('da-lat')),0,'public city isolation');
select is(list_community_places('nha-trang')->0->'hours'->>'state','hours_unknown','review does not invent verified hours');
select is(list_community_places('nha-trang')->0->'price'->>'state','unknown','review does not invent price');
select is(list_community_places('nha-trang')->0->>'moderation','community_reviewed','public origin remains explicit');
select ok(not (list_community_places('nha-trang')->0) ?| array['owner_id','actor_id','note','request_hash','idempotency_key','duplicate_hints','payload'],'public projection excludes all private fields');
select throws_ok($$select list_community_places('nha-trang',21,0)$$,'22023',null,'public page bounded');
select throws_ok($$select list_community_places('constructor',1,0)$$,'22023',null,'unsupported destination rejected');
reset role;
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select is((select count(*)::integer from place_submissions),0,'other owner still cannot read raw approved identity');
select is(submit_place(pg_temp.payload(),'f3400000-0000-4000-8000-000000000003')->>'status','submitted','other owner can submit same real candidate independently');
select is((select jsonb_array_length(duplicate_hints) from place_submissions),1,'approved public candidate creates suspected hint');
select is((select duplicate_hints->0->>'certainty' from place_submissions),'suspected','no uncertain auto-merge');
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000001',true);
select is(transition_place_submission(current_setting('test.submission_id')::uuid,3,'withdraw')->>'state','withdrawn','owner withdraws published record');
select is(jsonb_array_length(list_community_places('nha-trang')),0,'withdraw removes public visibility atomically');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,4,'restore')->>'state','submitted','owner restore requires new review');
select is(jsonb_array_length(list_community_places('nha-trang')),0,'restored is not auto-approved');
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000003',true);
select is(transition_place_submission(current_setting('test.submission_id')::uuid,5,'reject','Duplicate candidate requires correction')->>'state','rejected','moderator rejects');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,6,'restore')->>'state','verification','moderator restore goes to verification');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,7,'approve','Reviewed correction without claiming hours')->>'state','approved','moderator reapproves after review');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,8,'reject','Revoke inaccurate contribution')->>'state','rejected','moderator can revoke approval');
select is(jsonb_array_length(list_community_places('nha-trang')),0,'revocation immediately hides public projection');
select is((select count(*)::integer from place_submission_events where submission_id=current_setting('test.submission_id')::uuid),9,'every actual change has exactly one immutable audit version');
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000001',true);
select is(submit_place(pg_temp.payload(2),'f3400000-0000-4000-8000-000000000004')->>'status','submitted','quota fixture2');
select is(submit_place(pg_temp.payload(3),'f3400000-0000-4000-8000-000000000005')->>'status','submitted','quota fixture3');
select is(submit_place(pg_temp.payload(4),'f3400000-0000-4000-8000-000000000006')->>'status','submitted','quota fixture4');
select is(submit_place(pg_temp.payload(5),'f3400000-0000-4000-8000-000000000007')->>'status','submitted','quota fixture5');
select is(submit_place(pg_temp.payload(6),'f3400000-0000-4000-8000-000000000008')->>'status','rate_limited','sixth new submission blocked by durable quota');
select is(submit_place(pg_temp.payload(),'f3400000-0000-4000-8000-000000000001')->>'status','replayed','retry remains safe at quota');
select is((select count(*)::integer from place_submissions),5,'quota does not add rows');
reset role;
-- Inject a late audit failure: transaction must undo publication/state/version too.
create function pg_temp.fail_contribution_audit() returns trigger language plpgsql as $$begin raise exception 'Injected audit failure' using errcode='23514'; end;$$;
create trigger test_audit_failure before insert on place_submission_events for each row execute function pg_temp.fail_contribution_audit();
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select throws_ok($$select transition_place_submission(current_setting('test.submission_id')::uuid,9,'restore')$$,'23514',null,'late audit failure rolls back state transition');
select is((select version from place_submissions where id=current_setting('test.submission_id')::uuid),9,'failed audit does not increment version');
select is((select state from place_submissions where id=current_setting('test.submission_id')::uuid),'rejected','failed audit preserves prior moderation');
select is((select count(*)::integer from place_submission_events where submission_id=current_setting('test.submission_id')::uuid),9,'failed audit adds nothing');
reset role;
drop trigger test_audit_failure on place_submission_events;
select set_config('request.jwt.claim.sub','f3000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select is(transition_place_submission(current_setting('test.submission_id')::uuid,9,'withdraw')->>'state','withdrawn','withdraw quota fixture');
reset role;
insert into place_submissions(owner_id,idempotency_key,request_hash,payload,created_at)
select 'f3000000-0000-4000-8000-000000000001',gen_random_uuid(),encode(extensions.digest(pg_temp.payload(n)::text,'sha256'),'hex'),pg_temp.payload(n),statement_timestamp()-interval '2 days' from generate_series(20,35) n;
set local role authenticated;
select is((select count(*)::integer from place_submissions where state<>'withdrawn'),20,'twenty active fixture entries');
select is(transition_place_submission(current_setting('test.submission_id')::uuid,10,'restore')->>'status','rate_limited','restore cannot bypass active contribution cap');
select is((select state from place_submissions where id=current_setting('test.submission_id')::uuid),'withdrawn','rate-limited restore preserves record');
reset role;
select is((select count(*)::integer from places),60,'editorial records untouched');
select is((select count(*)::integer from places where status<>'draft'),0,'no editorial publication from contributions');
select * from finish();
rollback;
